/* Versioned, opt-in repair. Preview is pure; a complete database clone precedes apply. */
function wnbaAllPlayers(s){return [...s.teams.flatMap(t=>t.roster),...s.free,...(s.draftRights||[]).map(r=>r.player),...(s.draft?.prospects||[])]}
function wnbaReadContract(c){if(!c||c.version!==1||c.league!=='wnba'||!['veteran','rookie'].includes(c.kind)||!Number.isInteger(c.startYear)||!Number.isInteger(c.signedYear)||!WNBA_FINANCIAL_YEARS[c.ruleYear]||!Array.isArray(c.annual)||!c.annual.length||c.annual.length>7)throw Error('Invalid WNBA contract metadata');for(let i=0;i<c.annual.length;i++){const a=c.annual[i];if(a.year!==c.startYear+i||!Number.isSafeInteger(a.base)||a.base<0||a.base>1e9||!Number.isSafeInteger(a.guaranteed)||a.guaranteed<0||a.guaranteed>a.base||a.bonus!==undefined&&(!Number.isSafeInteger(a.bonus)||a.bonus<0)||![null,'pending','exercised','declined'].includes(a.option))throw Error('Invalid WNBA annual contract');}return copy(c);}
const wnbaOldValidate=validateCareerData;validateCareerData=function(raw){const out=wnbaOldValidate(raw);if(raw.wnbaFinance!==undefined){const f=raw.wnbaFinance;if(f?.version!==1||f.league!=='wnba'||!WNBA_FINANCIAL_YEARS[f.baseYear]||typeof f.progression!=='boolean'||!Array.isArray(f.dead)||f.dead.length>50000||f.dead.some(d=>!Number.isInteger(d.team)||d.team<0||d.team>=out.teams.length||!Number.isInteger(d.year)||!Number.isSafeInteger(d.amount)||d.amount<0))throw Error('Invalid WNBA financial ledger');if(f.hardships!==undefined&&(!Array.isArray(f.hardships)||f.hardships.some(g=>!Number.isInteger(g.team)||!out.teams[g.team]||!Number.isInteger(g.playerId)||!Number.isInteger(g.year)||!Number.isSafeInteger(g.amount)||g.amount<0||typeof g.active!=='boolean'||typeof g.reason!=='string')))throw Error('Invalid WNBA hardship authorization');out.wnbaFinance=copy(f);}
 const incoming=new Map(wnbaAllPlayers(raw).map(p=>[p.id,p]));for(const p of wnbaAllPlayers(out)){const q=incoming.get(p.id);if(q?.wnbaContract){p.wnbaContract=wnbaReadContract(q.wnbaContract);const current=p.wnbaContract.annual.find(a=>a.year===raw.year)||p.wnbaContract.annual[0];if(wnbaDollars(p.salary)!==current.base)throw Error('WNBA salary does not match its annual schedule');if(p.contractThrough!==wnbaContractEnd(p.wnbaContract))throw Error('WNBA contract end does not match its annual schedule');}if(q?.wnbaService){if(!Number.isInteger(q.wnbaService.seasons)||q.wnbaService.seasons<0||!Number.isInteger(q.wnbaService.asOf))throw Error('Invalid WNBA service record');p.wnbaService=copy(q.wnbaService);}if(q?.wnbaRights){if(!Array.isArray(q.wnbaRights.seasons)||q.wnbaRights.seasons.length>10||q.wnbaRights.seasons.some(v=>!Number.isInteger(v.year)||typeof v.teamKey!=='string'))throw Error('Invalid WNBA rights history');p.wnbaRights=copy(q.wnbaRights);}}
 return out;};
function wnbaRepairPreview(s,selected=[]){const result={version:1,fingerprint:JSON.stringify(s),players:[],teams:[],blockers:[],next:null};if(wnbaEnabled(s)){result.blockers.push('This career already uses WNBA contracts v1; repeat repair makes no changes.');return result;}if(!wnbaHistorical(s)){result.blockers.push('This is not a historical WNBA career.');return result;}const y=s.leagueSettings.historicalYear,r=WNBA_FINANCIAL_YEARS[y];if(!r){result.blockers.push('Historical year unavailable.');return result;}
 const legacy=y<2003&&s.salaryCap===150&&s.leagueSettings.minContract===1&&s.leagueSettings.maxContract===52.5;
 const old=wnbaOldPreset('wnba',y);const matches=legacy||s.salaryCap===old.cap&&s.leagueSettings.minContract===old.rules.minContract&&s.leagueSettings.maxContract===old.rules.maxContract;
 if(!matches){result.blockers.push('Custom or ambiguous financial settings detected. They are preserved; automatic financial repair is unavailable.');return result;}
 if(s.freeAgency?.year===s.year||s.draft?.picks?.length||s.expansion?.active){result.blockers.push('Finish the active offseason/expansion before repairing financial rules.');return result;}
 const next=copy(s);next.wnbaFinance={version:1,league:'wnba',baseYear:y,financialYear:y,progression:false,dead:[],adjustments:[],repairVersion:1};wnbaApplySettings(next);const chosen=new Set(selected);
 for(const t of next.teams){const original=s.teams[t.id];let fixed=0;const candidates=[];for(const p of t.roster){const amount=wnbaDollars(p.salary),lo=wnbaMinimum(p,s.year,next),hi=wnbaMaximum(p,t,s.year,next),fault=amount<lo||amount>hi,formula=Math.abs(p.salary-Math.max(1,Math.round((p.ovr-56)*.53*10)/10))<1e-9;const status=p.wnbaContract?'existing contract metadata':fault&&formula&&legacy?'suspected legacy-generated (confirmation required)':fault?'ambiguous out-of-era contract':'within historical bounds — preserved';const row={id:p.id,name:p.name,team:t.city,before:amount,after:amount,status,selected:chosen.has(p.id)&&!p.wnbaContract};result.players.push(row);if(row.selected)candidates.push({p,row,lo,desired:wnbaDemandDollars(p,t,s.year,next)});else fixed+=amount;}
 const dead=(s.finances?.[t.id]?.dead||[]).filter(d=>d.through>=s.year).reduce((a,d)=>a+wnbaDollars(d.salary),0),minimum=candidates.reduce((a,v)=>a+v.lo,0),want=candidates.reduce((a,v)=>a+v.desired,0),room=r.cap-fixed-dead;
 if(room<minimum)result.blockers.push(t.city+': preserved contracts/dead salary leave insufficient room. Select only contracts you know were generated incorrectly; valid/custom obligations are never erased.');
 const factor=Math.max(0,Math.min(1,(room-minimum)/Math.max(1,want-minimum)));for(const {p,row,lo,desired} of candidates){row.after=lo+Math.floor((desired-lo)*factor);p.wnbaService={seasons:wnbaService(p,s.year),asOf:s.year,evidence:'simulation_estimate'};wnbaAssign(p,wnbaMakeContract(p,t,{year:s.year,salary:row.after,years:1,evidence:'user_confirmed_repair_estimate'},next),s.year);}
 const excess=Math.max(0,t.roster.length-r.rosterMax),surplus=candidates.slice().sort((a,b)=>a.p.ovr-b.p.ovr||a.p.id-b.p.id).slice(0,excess);if(surplus.length<excess)result.blockers.push(t.city+': roster exceeds historical model limit; preserved players cannot be removed by this repair.');for(const {p,row} of surplus){row.action='Move to free agency (explicit repair approval required)';t.roster=t.roster.filter(q=>q.id!==p.id);delete p.wnbaContract;delete p.contractThrough;next.free.push(p);}if(t.roster.length<r.rosterMin)result.blockers.push(t.city+': roster below required minimum.');
 for(const p of t.roster){if(!p.wnbaContract){const annual=Array.from({length:Math.max(1,(p.contractThrough??s.year)-s.year+1)},(_,i)=>({year:s.year+i,base:wnbaDollars(p.salary),guaranteed:wnbaDollars(p.salary),option:null}));p.wnbaContract={version:1,league:'wnba',startYear:s.year,signedYear:s.year,ruleYear:r.year,kind:'veteran',evidence:'preserved_legacy_unverified',source:'existing_save',annual,minimumLinked:false};p.contractThrough=wnbaContractEnd(p.wnbaContract);}}
 result.teams.push({name:t.city,before:original.roster.reduce((a,p)=>a+wnbaDollars(p.salary),0)+dead,after:wnbaLedger(t,s.year,next).total,cap:r.cap});}
 for(const p of next.free){delete p.wnbaContract;delete p.contractThrough;p.salary=wnbaMillions(wnbaDemandDollars(p,next.teams[0],s.year,next));const row=result.players.find(v=>v.id===p.id&&v.action);if(row)row.after=wnbaDollars(p.salary);}
 if(!selected.length)result.blockers.push('Select and confirm incorrectly generated contracts before applying.');
 result.next=next;return result;
}
let wnbaRepairSelection=[],wnbaRepairSnapshot=null,wnbaRepairBusy=false;
function showWNBARepair(){wnbaRepairSnapshot=wnbaRepairPreview(state,wnbaRepairSelection);const p=wnbaRepairSnapshot;titleModal('Preview WNBA contract repair · v1',`<p>No changes have been applied. This repair preserves identities, statistics and history. Selected faulty contracts become explicitly estimated one-season agreements. If a legacy roster exceeds the supported size, the preview explicitly proposes moving its lowest-rated selected players to free agency, preserving their identities and records; valid/custom contracts and dead money stay intact. The historical environment is frozen until you enable progression.</p><p>Legacy saves did not record contract provenance. A formula match is evidence of the bug, not proof that you did not customize it. Select only contracts you recognize as incorrect.</p><div class="scroll" style="max-height:45vh"><table><thead><tr><th>Repair</th><th>Player</th><th>Current</th><th>Proposed</th><th>Evidence</th></tr></thead><tbody>${p.players.map(v=>`<tr><td><input type="checkbox" aria-label="Repair ${escapeHTML(v.name)}" ${wnbaRepairSelection.includes(v.id)?'checked':''} onchange="wnbaSelectRepair(${v.id},this.checked)"></td><td>${escapeHTML(v.team+' · '+v.name)}</td><td>${wnbaFormat(v.before)}</td><td>${v.action?'Unsigned; estimated demand ':''}${wnbaFormat(v.after)}</td><td>${escapeHTML(v.status)}${v.action?'<br><strong>'+escapeHTML(v.action)+'</strong>':''}</td></tr>`).join('')}</tbody></table></div><button onclick="wnbaSelectSuspected()">Select suspected legacy-generated contracts for review</button><h3>Team payroll preview</h3><div class="scroll"><table>${p.teams.map(t=>`<tr><th>${escapeHTML(t.name)}</th><td>${wnbaFormat(t.before)} → ${wnbaFormat(t.after)}</td><td>Limit ${wnbaFormat(t.cap)}</td></tr>`).join('')}</table></div>${p.blockers.map(e=>'<p role="alert">'+escapeHTML(e)+'</p>').join('')}<p>A separate complete backup career will be saved first. Your original save is not changed if backup creation fails.</p><button class="primary" onclick="applyWNBARepair()" ${p.blockers.length||wnbaRepairBusy?'disabled':''}>Confirm selected repairs and create backup</button>`);}
function wnbaSelectRepair(id,yes){wnbaRepairSelection=wnbaRepairSelection.filter(v=>v!==id);if(yes)wnbaRepairSelection.push(id);showWNBARepair();}
function wnbaSelectSuspected(){wnbaRepairSelection=wnbaRepairSnapshot.players.filter(p=>p.status.startsWith('suspected')).map(p=>p.id);showWNBARepair();}
async function applyWNBARepair(){if(wnbaRepairBusy)return;const preview=wnbaRepairSnapshot;if(!preview||preview.fingerprint!==JSON.stringify(state))return toast('Career changed. Reopen the repair preview.');const checked=wnbaRepairPreview(state,wnbaRepairSelection);if(checked.blockers.length)return toast(checked.blockers[0]);if(!activeSaveId)return toast('Save the career before repairing it.');wnbaRepairBusy=true;const before=copy(state),id=activeSaveId;try{await requireCareerStore();if(await save()===false)throw Error('Current career could not be saved.');await saveQueue;if(!careerStore.exportBackup||!careerStore.importBackup)throw Error('Full database backup is unavailable. Repair stopped.');const backup=await careerStore.exportBackup(id);backup.record.name+=' · Before WNBA repair';const saved=await careerStore.importBackup(backup,newCareerId());updateRecordCache(saved);if(id!==activeSaveId||preview.fingerprint!==JSON.stringify(state))throw Error('Career changed during backup; reopen preview.');state=validateCareerData(checked.next);state.wnbaFinance.backupId=saved.id;if(await save()===false){state=before;throw Error('Repair could not be saved. Original and backup are retained.');}wnbaRepairSelection=[];wnbaRepairSnapshot=null;closeTitleModal();render();toast('WNBA repair applied. Complete backup is in Load Career.');}catch(e){toast(e.message)}finally{wnbaRepairBusy=false}}
